```javascript
function getMatchingObjects(obj, path) {
    const parts = path.split('.');
    let currentObject = obj;

    for (let i = 0; i < parts.length - 1; i++) {
        if (!currentObject || typeof currentObject !== 'object' || !currentObject.hasOwnProperty(parts[i])) {
            return [];
        }
        currentObject = currentObject[parts[i]];
    }

    // The last part should be directly available as an object
    const result = Object.entries(currentObject).filter(([key, val]) => 
        key === parts.slice(-1)[0] && JSON.stringify(val) === JSON.stringify(path)
    );

    return result;
}

